/**
 * GPC Asset Manifest — canonical asset discovery for editors + runtime.
 * Exposes window.GPC_ASSETS. Pure browser JS, no build step.
 *
 * Storage:
 *   - On-disk:    fetched from assets/manifest.json (generated by scripts/scan-assets.js)
 *   - Uploads:    localStorage 'gpc_asset_uploads' (data URLs)
 *   - Overrides:  localStorage 'gpc_asset_overrides' (per-id patches for on-disk)
 *
 * Asset schema:
 *   { id, path, name, tags:[], course?:'1'..'6', w, h,
 *     type:'sprite'|'animation', frameCount?, source:'on-disk'|'uploaded', hidden?:bool }
 *
 * Override schema (stored in gpc_asset_overrides per-id):
 *   { pivot?: { x: 0..1, y: 0..1 }  // normalised, top-left origin. Default (0.5, 1.0) = bottom-centre.
 *     colliders?: ColliderShape[]
 *     groundYOffset?: number
 *     anchor?: { tl: bool, tr: bool, bl: bool, br: bool }  // corner pin flags; default: all true }
 *
 * @typedef {{ x: number, y: number }} PivotPoint  // x: 0=left, 1=right; y: 0=top, 1=bottom
 */
(function () {
  'use strict';

  if (window.GPC_ASSETS) return; // idempotent

  // Project-agnostic config — host page may set window.GPC_ASSETS_CONFIG before
  // including this script to override defaults (manifest URL, storage keys, tag vocab).
  var CONFIG = (window.GPC_ASSETS_CONFIG || {});
  var MANIFEST_URL = CONFIG.manifestUrl || 'assets/manifest.json';
  var LS_UPLOADS = CONFIG.storageKeys && CONFIG.storageKeys.uploads || 'gpc_asset_uploads';
  var LS_OVERRIDES = CONFIG.storageKeys && CONFIG.storageKeys.overrides || 'gpc_asset_overrides';

  var TAG_VOCAB = (CONFIG.tagVocab && CONFIG.tagVocab.length) ? CONFIG.tagVocab.slice() : [
    'ui', 'background', 'ground', 'decoration', 'obstacle',
    'character', 'animation', 'ball', 'effect', 'icon',
  ];

  var listeners = { change: [] };
  var diskAssets = [];           // raw from manifest.json
  var overrides = readJSON(LS_OVERRIDES, {}); // {id: patch}
  var uploads = readJSON(LS_UPLOADS, []);     // [Asset]
  var ready = false;
  var readyPromise = null;

  // ----- helpers -----
  function readJSON(key, fallback) {
    try {
      var raw = localStorage.getItem(key);
      if (!raw) return fallback;
      var parsed = JSON.parse(raw);
      return parsed == null ? fallback : parsed;
    } catch (_) { return fallback; }
  }
  function writeJSON(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); }
    catch (e) { console.warn('[GPC_ASSETS] localStorage write failed', e); }
  }
  function emit(event) {
    (listeners[event] || []).slice().forEach(function (cb) {
      try { cb(); } catch (e) { console.error('[GPC_ASSETS] listener', e); }
    });
  }
  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function uid() {
    return 'up_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  }

  // Apply overrides on top of an on-disk asset.
  function withOverride(a) {
    var patch = overrides[a.id];
    if (!patch) return a;
    var merged = Object.assign({}, a, patch);
    if (patch.tags) merged.tags = patch.tags.slice();
    return merged;
  }

  // Merged view of all assets (on-disk + overrides + uploads), excluding hidden.
  function allAssets() {
    var result = [];
    for (var i = 0; i < diskAssets.length; i++) {
      var merged = withOverride(diskAssets[i]);
      if (!merged.hidden) result.push(merged);
    }
    for (var j = 0; j < uploads.length; j++) {
      if (!uploads[j].hidden) result.push(uploads[j]);
    }
    return result;
  }

  // ----- public API -----
  function list(opts) {
    opts = opts || {};
    var pool = allAssets();
    if (opts.course) {
      pool = pool.filter(function (a) { return a.course === String(opts.course); });
    }
    if (opts.tags && opts.tags.length) {
      pool = pool.filter(function (a) {
        return opts.tags.every(function (t) { return a.tags.indexOf(t) >= 0; });
      });
    }
    if (opts.anyTag && opts.anyTag.length) {
      pool = pool.filter(function (a) {
        return opts.anyTag.some(function (t) { return a.tags.indexOf(t) >= 0; });
      });
    }
    return pool;
  }

  function get(id) {
    for (var i = 0; i < uploads.length; i++) {
      if (uploads[i].id === id) return uploads[i];
    }
    for (var j = 0; j < diskAssets.length; j++) {
      if (diskAssets[j].id === id) return withOverride(diskAssets[j]);
    }
    return null;
  }

  function update(id, patch) {
    if (!patch || typeof patch !== 'object') return get(id);
    var allowed = ['name', 'tags', 'w', 'h', 'course', 'crop', 'hidden'];
    var clean = {};
    allowed.forEach(function (k) {
      if (patch[k] !== undefined) clean[k] = patch[k];
    });

    // Uploaded?
    for (var i = 0; i < uploads.length; i++) {
      if (uploads[i].id === id) {
        Object.assign(uploads[i], clean);
        writeJSON(LS_UPLOADS, uploads);
        emit('change');
        return uploads[i];
      }
    }
    // On-disk → store as override
    var existing = null;
    for (var j = 0; j < diskAssets.length; j++) {
      if (diskAssets[j].id === id) { existing = diskAssets[j]; break; }
    }
    if (!existing) return null;
    overrides[id] = Object.assign({}, overrides[id] || {}, clean);
    writeJSON(LS_OVERRIDES, overrides);
    emit('change');
    return withOverride(existing);
  }

  function remove(id) {
    // Uploaded → soft-delete (drop from uploads)
    var idx = -1;
    for (var i = 0; i < uploads.length; i++) {
      if (uploads[i].id === id) { idx = i; break; }
    }
    if (idx >= 0) {
      uploads.splice(idx, 1);
      writeJSON(LS_UPLOADS, uploads);
      emit('change');
      return;
    }
    // On-disk → mark hidden via override
    for (var j = 0; j < diskAssets.length; j++) {
      if (diskAssets[j].id === id) {
        overrides[id] = Object.assign({}, overrides[id] || {}, { hidden: true });
        writeJSON(LS_OVERRIDES, overrides);
        emit('change');
        return;
      }
    }
  }

  function add(input, meta) {
    meta = meta || {};
    var id = uid();
    var name = meta.name || ('upload-' + id);
    var tags = (meta.tags && meta.tags.length) ? meta.tags.slice() : ['decoration'];
    var asset = {
      id: id,
      path: '',           // filled below
      name: name,
      tags: tags,
      w: meta.w || 0,
      h: meta.h || 0,
      type: tags.indexOf('animation') >= 0 ? 'animation' : 'sprite',
      source: 'uploaded',
    };
    if (meta.course) asset.course = String(meta.course);
    if (meta.frameCount) asset.frameCount = meta.frameCount;

    function finalize(dataUrl) {
      asset.path = dataUrl;
      // Try to determine dimensions if not provided
      if (!asset.w || !asset.h) {
        var img = new Image();
        img.onload = function () {
          asset.w = img.naturalWidth;
          asset.h = img.naturalHeight;
          writeJSON(LS_UPLOADS, uploads);
          emit('change');
        };
        img.src = dataUrl;
      }
      uploads.push(asset);
      writeJSON(LS_UPLOADS, uploads);
      emit('change');
    }

    if (typeof input === 'string') {
      finalize(input);
      return asset;
    }
    if (input && typeof input === 'object' && typeof FileReader !== 'undefined') {
      var reader = new FileReader();
      reader.onload = function (e) { finalize(e.target.result); };
      reader.readAsDataURL(input);
      return asset; // will populate async; listeners get 'change' on completion
    }
    throw new Error('GPC_ASSETS.add: input must be File or data URL string');
  }

  function on(event, cb) {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push(cb);
  }

  function init() {
    if (readyPromise) return readyPromise;
    readyPromise = new Promise(function (resolve) {
      // Try fetch; fall back to empty (e.g. file:// or missing manifest)
      var url = MANIFEST_URL + '?v=' + Date.now();
      var done = function () { ready = true; emit('change'); resolve(api); };
      if (typeof fetch !== 'function') { done(); return; }
      fetch(url, { cache: 'no-cache' })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (data) {
          if (data && Array.isArray(data.assets)) {
            diskAssets = data.assets;
            // If manifest carries a CDN base, update GPC_ASSET_CDN and rewrite paths.
            if (data.cdnBase) {
              if (window.GPC_ASSET_CDN) {
                window.GPC_ASSET_CDN.base = data.cdnBase;
              }
              diskAssets = diskAssets.map(function (a) {
                // If cdnUrl already baked in by migration script, use it directly.
                if (a.cdnUrl) {
                  return Object.assign({}, a, { originalPath: a.path, path: a.cdnUrl });
                }
                // Otherwise resolve via GPC_ASSET_CDN if available.
                if (window.GPC_ASSET_CDN && a.path && a.path.indexOf('http') !== 0) {
                  return Object.assign({}, a, {
                    originalPath: a.path,
                    path: window.GPC_ASSET_CDN.resolve(a.path),
                  });
                }
                return a;
              });
            }
          }
          done();
        })
        .catch(function () { done(); });
    });
    return readyPromise;
  }

  var api = {
    list: list,
    get: get,
    update: update,
    remove: remove,
    add: add,
    on: on,
    TAG_VOCAB: TAG_VOCAB,
    ready: function () { return readyPromise || init(); },
    isReady: function () { return ready; },
    _internal: {
      reloadManifest: function () { readyPromise = null; return init(); },
      clearOverrides: function () { overrides = {}; writeJSON(LS_OVERRIDES, overrides); emit('change'); },
      clearUploads: function () { uploads = []; writeJSON(LS_UPLOADS, uploads); emit('change'); },
    },
  };

  window.GPC_ASSETS = api;
  // Project-agnostic alias. Prefer `window.AssetSystem` in new projects;
  // `window.GPC_ASSETS` is preserved for backward compatibility.
  if (!window.AssetSystem) window.AssetSystem = api;
  init();
})();
